def _insert_simple(table: str, rows: list[tuple[str, str]]) -> None:
    tbl = sa.table(table, sa.column("code"), sa.column("name"), sa.column("sort_order"))
    op.bulk_insert(tbl, [
        {"code": code, "name": name, "sort_order": (i + 1) * 10}
        for i, (code, name) in enumerate(rows)
    ])
